const { describe, it, beforeEach } = require('node:test');
const assert = require('node:assert/strict');
const ShoppingCart = require('../src/cart');

function assertClose(actual, expected, epsilon = 1e-9) {
  assert.ok(
    Math.abs(actual - expected) < epsilon,
    `expected ${actual} to be close to ${expected}`
  );
}

describe('ShoppingCart', () => {
  let cart;

  beforeEach(() => {
    cart = new ShoppingCart();
  });

  describe('constructor', () => {
    it('starts empty with no discount', () => {
      assert.deepEqual(cart.items, []);
      assert.equal(cart.discount, 0);
      assert.equal(cart.getItemCount(), 0);
    });
  });

  describe('addItem', () => {
    it('adds a new item', () => {
      cart.addItem('apple', 1.5, 2);
      assert.deepEqual(cart.items, [{ name: 'apple', price: 1.5, quantity: 2 }]);
      assert.equal(cart.getItemCount(), 1);
    });

    it('adds multiple distinct items', () => {
      cart.addItem('apple', 1, 1);
      cart.addItem('banana', 2, 3);
      assert.equal(cart.getItemCount(), 2);
    });

    it('merges quantity when the same item is added again', () => {
      cart.addItem('apple', 1, 2);
      cart.addItem('apple', 1, 3);
      assert.equal(cart.getItemCount(), 1);
      assert.equal(cart.items[0].quantity, 5);
    });

    it('allows a price of zero (free items)', () => {
      cart.addItem('sticker', 0, 1);
      assert.equal(cart.getItemCount(), 1);
      assert.equal(cart.getTotal(), 0);
    });

    // Bug 1 regression tests
    describe('Bug 1: rejects invalid price and quantity', () => {
      it('throws on a negative price', () => {
        assert.throws(() => cart.addItem('apple', -1, 1), RangeError);
        assert.equal(cart.getItemCount(), 0);
      });

      it('throws on a negative quantity', () => {
        assert.throws(() => cart.addItem('apple', 1, -1), RangeError);
        assert.equal(cart.getItemCount(), 0);
      });

      it('does not let a negative quantity reduce an existing item', () => {
        cart.addItem('apple', 1, 5);
        assert.throws(() => cart.addItem('apple', 1, -3), RangeError);
        assert.equal(cart.items[0].quantity, 5);
      });

      it('throws on a zero quantity', () => {
        assert.throws(() => cart.addItem('apple', 1, 0), RangeError);
        assert.equal(cart.getItemCount(), 0);
      });

      it('throws on a fractional quantity', () => {
        assert.throws(() => cart.addItem('apple', 1, 1.5), RangeError);
      });

      it('throws on non-numeric or non-finite price', () => {
        assert.throws(() => cart.addItem('apple', '5', 1), TypeError);
        assert.throws(() => cart.addItem('apple', NaN, 1), TypeError);
        assert.throws(() => cart.addItem('apple', Infinity, 1), TypeError);
        assert.equal(cart.getItemCount(), 0);
      });

      it('throws on non-numeric quantity', () => {
        assert.throws(() => cart.addItem('apple', 1, '2'), TypeError);
        assert.throws(() => cart.addItem('apple', 1, NaN), TypeError);
        assert.equal(cart.getItemCount(), 0);
      });
    });
  });

  describe('removeItem', () => {
    // Bug 2 regression tests
    describe('Bug 2: removes only the named item and handles missing items', () => {
      it('removes the named item', () => {
        cart.addItem('apple', 1, 1);
        cart.removeItem('apple');
        assert.equal(cart.getItemCount(), 0);
      });

      it('keeps the other items', () => {
        cart.addItem('apple', 1, 1);
        cart.addItem('banana', 2, 1);
        cart.addItem('cherry', 3, 1);
        cart.removeItem('banana');
        assert.deepEqual(cart.items.map(i => i.name), ['apple', 'cherry']);
      });

      it('does not rename the remaining items', () => {
        cart.addItem('apple', 1, 1);
        cart.addItem('banana', 2, 1);
        cart.removeItem('apple');
        assert.deepEqual(cart.items, [{ name: 'banana', price: 2, quantity: 1 }]);
      });

      it('returns true when an item was removed', () => {
        cart.addItem('apple', 1, 1);
        assert.equal(cart.removeItem('apple'), true);
      });

      it('returns false and leaves the cart unchanged when the item is missing', () => {
        cart.addItem('apple', 1, 1);
        assert.equal(cart.removeItem('pear'), false);
        assert.deepEqual(cart.items, [{ name: 'apple', price: 1, quantity: 1 }]);
      });

      it('returns false when removing from an empty cart', () => {
        assert.equal(cart.removeItem('apple'), false);
        assert.equal(cart.getItemCount(), 0);
      });
    });
  });

  describe('getTotal', () => {
    // Bug 3 regression tests
    describe('Bug 3: iterates exactly over the items (no off-by-one)', () => {
      it('returns 0 for an empty cart instead of throwing', () => {
        assert.equal(cart.getTotal(), 0);
      });

      it('totals a single item', () => {
        cart.addItem('apple', 2, 3);
        assert.equal(cart.getTotal(), 6);
      });

      it('totals multiple items', () => {
        cart.addItem('apple', 2, 3);
        cart.addItem('banana', 0.5, 4);
        cart.addItem('cherry', 10, 1);
        assert.equal(cart.getTotal(), 18);
      });
    });

    it('reflects merged quantities', () => {
      cart.addItem('apple', 2, 1);
      cart.addItem('apple', 2, 2);
      assert.equal(cart.getTotal(), 6);
    });

    it('reflects removed items', () => {
      cart.addItem('apple', 2, 1);
      cart.addItem('banana', 5, 1);
      cart.removeItem('banana');
      assert.equal(cart.getTotal(), 2);
    });

    it('handles decimal prices', () => {
      cart.addItem('a', 0.1, 3);
      assertClose(cart.getTotal(), 0.3);
    });

    // Bug 4 regression tests
    describe('Bug 4: subtracts the discount from the total', () => {
      it('applies a 10% discount', () => {
        cart.addItem('item', 100, 1);
        cart.applyDiscount(10);
        assert.equal(cart.getTotal(), 90);
      });

      it('applies a 25% discount across multiple items', () => {
        cart.addItem('a', 20, 2);
        cart.addItem('b', 10, 4);
        cart.applyDiscount(25);
        assert.equal(cart.getTotal(), 60);
      });

      it('never produces a discounted total above the undiscounted total', () => {
        cart.addItem('item', 50, 2);
        const before = cart.getTotal();
        cart.applyDiscount(30);
        assert.ok(cart.getTotal() < before);
      });

      it('a 100% discount makes the total 0', () => {
        cart.addItem('item', 42, 3);
        cart.applyDiscount(100);
        assert.equal(cart.getTotal(), 0);
      });

      it('a 0% discount leaves the total unchanged', () => {
        cart.addItem('item', 42, 3);
        cart.applyDiscount(0);
        assert.equal(cart.getTotal(), 126);
      });

      it('applies the discount to items added after the discount', () => {
        cart.applyDiscount(50);
        cart.addItem('item', 10, 2);
        assert.equal(cart.getTotal(), 10);
      });

      it('handles fractional discount percentages', () => {
        cart.addItem('item', 200, 1);
        cart.applyDiscount(12.5);
        assertClose(cart.getTotal(), 175);
      });
    });
  });

  describe('applyDiscount', () => {
    it('stores a valid discount', () => {
      cart.applyDiscount(15);
      assert.equal(cart.discount, 15);
    });

    it('accepts the boundary values 0 and 100', () => {
      cart.applyDiscount(0);
      assert.equal(cart.discount, 0);
      cart.applyDiscount(100);
      assert.equal(cart.discount, 100);
    });

    it('replaces a previous discount rather than stacking', () => {
      cart.addItem('item', 100, 1);
      cart.applyDiscount(10);
      cart.applyDiscount(20);
      assert.equal(cart.getTotal(), 80);
    });

    // Bug 5 regression tests
    describe('Bug 5: rejects discounts outside 0-100', () => {
      it('throws on a discount above 100', () => {
        assert.throws(() => cart.applyDiscount(101), RangeError);
        assert.throws(() => cart.applyDiscount(150), RangeError);
      });

      it('throws on a negative discount', () => {
        assert.throws(() => cart.applyDiscount(-1), RangeError);
        assert.throws(() => cart.applyDiscount(-50), RangeError);
      });

